{"id":"7ae5b4dc-df4b-4df1-8b13-f466ceedf75a","inserted_at":"2026-07-08T00:36:43.406491+00:00","updated_at":"2026-07-08T00:36:43.406491+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- ==========================================\r\n-- RIPRISTINO LOGICA DINAMICA (METE CONSIGLIATE E FLUSSI)\r\n-- ==========================================\r\n\r\n-- 1. Impostiamo due mete come 'Consigliate' per popolare la prima sezione in Home\r\nUPDATE public.pois \r\nSET is_recommended = true\r\nWHERE name ILIKE '%Ipogeo%' OR name ILIKE '%MuDi%';\r\n\r\n-- 2. Simuliamo l'algoritmo Anti-Crowding sul Castello Aragonese (Affollamento critico > 80%)\r\nUPDATE public.pois \r\nSET crowd_level = 85\r\nWHERE name ILIKE '%Castello Aragonese%';\r\n\r\n-- 3. Assegniamo al Castello un'alternativa sicura (Tempio di Poseidone) per il Routing\r\nUPDATE public.pois \r\nSET alternative_poi_id = (SELECT id FROM public.pois WHERE name ILIKE '%Tempio di Poseidone%' LIMIT 1)\r\nWHERE name ILIKE '%Castello Aragonese%';\r\n\r\n-- 4. Aggiungiamo il tag 'Bonus Idrico' (Stazione Refill) a un paio di POI\r\nUPDATE public.pois \r\nSET has_water = true\r\nWHERE name ILIKE '%Tempio%' OR name ILIKE '%Saturo%';","content_id":"7ae5b4dc-df4b-4df1-8b13-f466ceedf75a","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
